# get_obj ----
## Setup ----
# Load or prepare any necessary data for testing
fit_with_optimization_big <- FIMS::fit_with_optimization_big
fit_without_optimization_big <- FIMS::fit_without_optimization_big

expected_names <- c(
  "par", "fn", "gr", "he", "hessian", "method", "retape",
  "env", "report", "simulate"
)

## IO correctness ----
test_that("`get_obj()` works with fit_with_optimization_big", {  
  obj <- get_obj(fit_with_optimization_big)

  #' @description Test that `get_obj()` returns correct output for the `obj` slot.
  expect_equal(
    object = obj,
    expected = fit_with_optimization_big@obj
  )

  #' @description Test that `get_obj()` returns correct names for the `obj` slot.
  expect_equal(
    object = names(obj),
    expected = expected_names
  )
})

test_that("`get_obj()` works with fit_without_optimization_big", {  
  obj <- get_obj(fit_without_optimization_big)

  #' @description Test that `get_obj()` returns correct output for the `obj` slot.
  expect_equal(
    object = obj,
    expected = fit_without_optimization_big@obj
  )

  #' @description Test that `get_obj()` returns correct names for the `obj` slot.
  expect_equal(
    object = names(obj),
    expected = expected_names
  )
})

## Edge handling ----
test_that("`get_obj()` returns correct outputs for edge cases", {
  #' @description Test that `get_obj()` returns an error when given invalid input.
  expect_error(
    object = get_obj("invalid_input")
  )
})

